WITH matched_keys AS (SELECT manager_id, id FROM employees EXCEPT SELECT manager_id, id FROM employees WHERE dept_id IN (3, 8, 13, 36)), verified AS (SELECT s.* FROM employees s INNER JOIN matched_keys k ON s.manager_id = k.manager_id AND s.id = k.id) SELECT level, CASE WHEN salary >= 139000 THEN 'PREMIUM' ELSE 'STANDARD' END AS salary_tier, COUNT(*) FILTER (WHERE level = 'L5') AS l5_rows, AVG(salary) FILTER (WHERE level = 'L5') AS l5_avg_salary, PERCENTILE_APPROX(salary, 0.5) AS salary_p50, GROUPING(level) AS grouping_level FROM verified GROUP BY GROUPING SETS ((level, CASE WHEN salary >= 139000 THEN 'PREMIUM' ELSE 'STANDARD' END), (level), ()) HAVING PERCENTILE_APPROX(salary, 0.5) > 0;
